import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int k = fs.nextInt();
        int c = fs.nextInt();

        long[] prefix = new long[n + 1];
        int[] values = c == 1 ? new int[n] : null;

        for (int i = 0; i < n; i++) {
            int value = fs.nextInt();
            prefix[i + 1] = prefix[i] + value;
            if (values != null) values[i] = value;
        }

        long minCovered;
        if (c == 1) {
            Arrays.sort(values);
            minCovered = 0;
            for (int i = 0; i < k; i++) {
                minCovered += values[i];
            }
        } else {
            final long INF = Long.MAX_VALUE / 4;
            long[] previous = new long[n + 1];
            long[] current = new long[n + 1];

            for (int count = 1; count <= k; count++) {
                current[0] = INF;
                for (int i = 1; i <= n; i++) {
                    long best = current[i - 1];
                    if (i >= c) {
                        long before = previous[i - c];
                        if (before != INF) {
                            long candidate = before + prefix[i] - prefix[i - c];
                            if (candidate < best) best = candidate;
                        }
                    }
                    current[i] = best;
                }

                long[] temp = previous;
                previous = current;
                current = temp;
            }

            minCovered = previous[n];
        }

        System.out.println(prefix[n] - minCovered);
    }
}
